"""Generate the SDK based on the aas-core-meta model and the snippets."""

import argparse
import os
import pathlib
import re
import subprocess
import sys

# NOTE (aaronzi, 2026-11-05):
# aas-core-codegen does not emit any copyright or license information, so we
# prepend the header to the generated files ourselves. Otherwise, the headers
# would be lost on every re-generation.
#
# REUSE-IgnoreStart
_LICENSE_HEADER = """\
// SPDX-FileCopyrightText: 2026 aas-core3.1-cpp AUTHORS
//
// SPDX-License-Identifier: MIT

"""
# REUSE-IgnoreEnd

_LEADING_SPDX_COMMENTS_RE = re.compile(r"\A(?://\s*(?:SPDX-[A-Za-z-]+:.*)?\n|\n)*")

_GENERATED_MARKER = "// This code has been automatically generated by aas-core-codegen."


def _prepend_license_header(text: str) -> str:
    """Replace any leading SPDX comment block in ``text`` with our license header."""
    return _LICENSE_HEADER + _LEADING_SPDX_COMMENTS_RE.sub("", text, count=1)


def _add_license_headers(output_dir: pathlib.Path) -> None:
    """Prepend the license header to all the files generated by aas-core-codegen."""
    for subdir in ["include", "src", "test"]:
        for path in sorted(
            [
                *(output_dir / subdir).glob("**/*.cpp"),
                *(output_dir / subdir).glob("**/*.hpp"),
            ]
        ):
            text = path.read_text(encoding="utf-8")
            if _GENERATED_MARKER not in text:
                continue

            path.write_text(_prepend_license_header(text), encoding="utf-8")


# NOTE (aaronzi, 2026-11-05):
# The base64 encoder and decoder in the generated src/stringification.cpp have
# been adapted from other projects. We mark them with REUSE snippet tags so that
# their original copyright and license are kept. The pinned aas-core-codegen
# does not emit these tags yet, so we replace its old comments with the tagged
# ones and close each snippet after its function. Once aas-core-codegen emits
# the tags itself, this step changes nothing.
#
# REUSE-IgnoreStart
_OLD_BASE64_ENCODER_COMMENT = """\
// The following encoder has been adapted from Jouni Malinen <j@w1.fi> to work with
// std::string. The original source code is available at:
// https://web.mit.edu/freebsd/head/contrib/wpa/src/utils/base64.c
//
// See also the following StackOverflow question for a benchmark:
// https://stackoverflow.com/questions/342409/how-do-i-base64-encode-decode-in-c/41094722#41094722
"""

_BASE64_ENCODER_SNIPPET_TAGS = """\
// SPDX-SnippetBegin
// SPDX-SnippetCopyrightText: 2005-2011 Jouni Malinen <j@w1.fi>
// SPDX-License-Identifier: BSD-3-Clause
"""

_BASE64_ENCODER_COMMENT = (
    _BASE64_ENCODER_SNIPPET_TAGS
    + """\
//
// The following encoder has been adapted from base64.c of wpa_supplicant/hostapd
// by Jouni Malinen <j@w1.fi> to work with std::string. The original source code
// is available at:
// https://web.mit.edu/freebsd/head/contrib/wpa/src/utils/base64.c
//
// See also the following StackOverflow question for a benchmark:
// https://stackoverflow.com/questions/342409/how-do-i-base64-encode-decode-in-c/41094722#41094722
"""
)

_OLD_BASE64_DECODER_COMMENT = """\
// The following decoder is vaguely based on:
// https://github.com/danguer/blog-examples/blob/master/js/base64-binary.js,
// https://github.com/niklasvh/base64-arraybuffer/blob/master/src/index.ts and
// https://github.com/beatgammit/base64-js/blob/master/index.js.
"""

_BASE64_DECODER_SNIPPET_TAGS = """\
// SPDX-SnippetBegin
// SPDX-SnippetCopyrightText: 2012 Niklas von Hertzen
// SPDX-License-Identifier: MIT
"""

_BASE64_DECODER_COMMENT = (
    _BASE64_DECODER_SNIPPET_TAGS
    + """\
//
// The following decoder has been adapted from the decode function of
// base64-arraybuffer by Niklas von Hertzen, and extended with input validation.
// The original source code is available at:
// https://github.com/niklasvh/base64-arraybuffer/blob/master/src/index.ts
"""
)

_SNIPPET_BEGIN = "// SPDX-SnippetBegin\n"
_SNIPPET_END = "// SPDX-SnippetEnd\n"
# REUSE-IgnoreEnd

# (old comment, new comment, tags of the new comment, start of the function
# which closes the snippet)
_BASE64_SNIPPETS = [
    (
        _OLD_BASE64_ENCODER_COMMENT,
        _BASE64_ENCODER_COMMENT,
        _BASE64_ENCODER_SNIPPET_TAGS,
        "\nstd::string Base64Encode(\n",
    ),
    (
        _OLD_BASE64_DECODER_COMMENT,
        _BASE64_DECODER_COMMENT,
        _BASE64_DECODER_SNIPPET_TAGS,
        "\n> Base64Decode(\n",
    ),
]


def _attribute_base64_snippets(text: str) -> str:
    """
    Mark the base64 code in ``text`` with REUSE snippet tags.

    >>> encoder = (
    ...     _OLD_BASE64_ENCODER_COMMENT
    ...     + "\\nstd::string Base64Encode(\\n) {\\n  return x;\\n}\\n\\n"
    ... )
    >>> decoder = (
    ...     _OLD_BASE64_DECODER_COMMENT
    ...     + "\\nvoid Lookup() {\\n}\\n\\nint\\n> Base64Decode(\\n) {\\n}\\n\\n"
    ... )
    >>> once = _attribute_base64_snippets(encoder + decoder)
    >>> once.count(_SNIPPET_END)
    2
    >>> "  return x;\\n}\\n" + _SNIPPET_END + "\\n" + _SNIPPET_BEGIN in once
    True
    >>> _attribute_base64_snippets(once) == once
    True
    >>> _attribute_base64_snippets("no base64 here")  # doctest: +ELLIPSIS
    Traceback (most recent call last):
    ...
    RuntimeError: Neither the old comment nor the snippet tags of the base64 code ...
    """
    for old_comment, new_comment, snippet_tags, function_start in _BASE64_SNIPPETS:
        if snippet_tags in text:
            # NOTE (aaronzi, 2026-11-05):
            # The snippet is already tagged, either by aas-core-codegen or by
            # an earlier run of this function.
            continue

        if text.count(old_comment) != 1:
            raise RuntimeError(
                "Neither the old comment nor the snippet tags of the base64 code "
                f"have been found exactly once. Expected the comment:\n{old_comment}"
            )

        text = text.replace(old_comment, new_comment)

        function_start_index = text.find(function_start, text.index(new_comment))
        if function_start_index == -1:
            raise RuntimeError(
                f"The function {function_start.strip()!r} has not been found "
                "after its comment."
            )

        closing_brace = "\n}\n"
        closing_brace_index = text.find(closing_brace, function_start_index)
        if closing_brace_index == -1:
            raise RuntimeError(
                f"The end of the function {function_start.strip()!r} "
                "has not been found."
            )

        end_index = closing_brace_index + len(closing_brace)
        if not text.startswith(_SNIPPET_END, end_index):
            text = text[:end_index] + _SNIPPET_END + text[end_index:]

    if text.count(_SNIPPET_BEGIN) != text.count(_SNIPPET_END):
        raise RuntimeError(
            "The number of snippet begin and end tags differ: "
            f"{text.count(_SNIPPET_BEGIN)} versus {text.count(_SNIPPET_END)}."
        )

    return text


def _add_base64_snippet_tags(output_dir: pathlib.Path) -> None:
    """Mark the generated base64 code with REUSE snippet tags."""
    path = output_dir / "src" / "stringification.cpp"
    text = path.read_text(encoding="utf-8")
    path.write_text(_attribute_base64_snippets(text), encoding="utf-8")


def main() -> int:
    """Execute the main routine."""
    repo_root = pathlib.Path(os.path.realpath(__file__)).parent.parent

    default_meta_model_path = os.path.relpath(
        str(repo_root / "dev_scripts" / "codegen" / "meta_model.py"),
        os.getcwd(),
    )

    default_snippet_dir = os.path.relpath(
        str(repo_root / "dev_scripts" / "codegen" / "snippets"), os.getcwd()
    )

    default_output_dir = os.path.relpath(str(repo_root), os.getcwd())

    parser = argparse.ArgumentParser(
        description=__doc__, formatter_class=argparse.ArgumentDefaultsHelpFormatter
    )
    parser.add_argument(
        "--meta_model", help="Path to the meta-model", default=default_meta_model_path
    )
    parser.add_argument(
        "--snippet_dir",
        help="Path to the directory containing implementation-specific snippets",
        default=default_snippet_dir,
    )
    parser.add_argument(
        "--output_dir",
        help="Path to the directory where the generated files are to be output",
        default=default_output_dir,
    )
    args = parser.parse_args()

    meta_model_path = pathlib.Path(args.meta_model)
    snippet_dir = pathlib.Path(args.snippet_dir)
    output_dir = pathlib.Path(args.output_dir)

    subprocess.run(
        [
            "aas-core-codegen",
            "--model_path",
            str(meta_model_path),
            "--snippets_dir",
            str(snippet_dir),
            "--output_dir",
            str(output_dir),
            "--target",
            "cpp",
        ],
        check=True,
    )

    _add_license_headers(output_dir)
    _add_base64_snippet_tags(output_dir)

    return 0


if __name__ == "__main__":
    sys.exit(main())
